function isBalanced(s: string): boolean {
  const opener: Record<string, string> = { ")": "(", "]": "[", "}": "{" };
  const stack: string[] = [];
  for (const c of s) {
    if (c in opener) {
      if (stack.length === 0 || stack.pop() !== opener[c]) return false;
    } else {
      stack.push(c);
    }
  }
  return stack.length === 0;
}

